style.css:
@-moz-document domain("web.whatsapp.com") {
/* --- CONFIGURACIÓN PRINCIPAL --- */
  
  /* 1. Fondo de Paisaje (Cambiable) */
  body::after {
    content: "";
    /* URL de la imagen. Puedes cambiar esta URL por la que quieras */
    background-image: url('https://images.unsplash.com/photo-1519681393784-d120267933ba?q=80&w=2560&auto=format&fit=crop'); 
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    z-index: -1;
  }

  /* 2. Quitar fondos sólidos por defecto */
  #app, ._8nE1Y, .pane-side, .copyable-area, [data-testid="conversation-panel-wrapper"] {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* 3. Definir colores de texto para fondo claro (vidrio blanco) */
  :root {
    --text-primary: #111 !important;
    --text-secondary: #555 !important;
    --icon: #444 !important;
  }

  /* --- EFECTO LIQUID GLASS (GLASSMORPHISM) --- */

  /* Estilo común para todos los paneles de vidrio */
  .pane-side, /* Lista de contactos */
  [data-testid="conversation-panel-header"], /* Cabecera del chat */
  [data-testid="sidebar-header"], /* Mi cabecera (perfil) */
  footer, /* Panel de entrada de mensaje */
  [data-testid="msg-bubble"] /* Burbujas de mensaje */ {
    background-color: rgba(255, 255, 255, 0.2) !important; /* Vidrio semitransparente blanco */
    backdrop-filter: blur(15px) !important; /* El desenfoque clave */
    -webkit-backdrop-filter: blur(15px) !important; /* Soporte Safari/Old Chrome */
    border: 1px solid rgba(255, 255, 255, 0.1) !important; /* Borde sutil del vidrio */
    border-radius: 12px !important; /* Bordes redondeados modernos */
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1) !important; /* Sombra sutil */
  }

  /* --- AJUSTES ESPECÍFICOS --- */

  /* Lista de Chats */
  .pane-side {
    margin: 10px; /* Margen para efecto flotante */
    height: calc(100% - 20px) !important;
  }
  
  /* Panel de conversación principal (flotante) */
  [data-testid="conversation-panel-wrapper"] {
    margin: 10px 10px 10px 0;
    overflow: hidden;
  }

  /* Fondo del área de mensajes (sin patrón) */
  [data-testid="conversation-panel-messages"] {
    background-image: none !important;
    background-color: transparent !important;
  }

  /* Burbujas de Mensaje */
  [data-testid="msg-bubble"] {
    max-width: 65%;
    margin-bottom: 8px !important;
    padding: 8px 12px !important;
  }

  /* Diferenciar burbuja de entrada y salida */
  .message-in [data-testid="msg-bubble"] {
    background-color: rgba(255, 255, 255, 0.35) !important; /* Vidrio más claro para entrada */
  }
  .message-out [data-testid="msg-bubble"] {
    background-color: rgba(220, 248, 198, 0.4) !important; /* Tinte verde suave para salida */
  }

  /* Textos y Elementos */
  .pane-chat-last-msg, .pane-chat-date, .message-text, .msg-text {
    color: var(--text-primary) !important;
  }

  /* Input de mensaje */
  [data-testid="conversation-panel-input"] {
    background-color: rgba(255, 255, 255, 0.1) !important;
    border-radius: 20px !important;
  }
}
